// generated by gen_matrix (full carrier composition matrix).
use vehje_bench_carrier as c;
use mockspace_bench_core::{timed, FfiBenchCall};
use mockspace_bench_macro::bench_variant;
#[allow(unused_imports)]
use std::sync::OnceLock;

#[bench_variant("carrier_nat_wideselect_stencil", sizes = [64, 256, 1024, 4096, 16384])]
fn run<const N: usize>(input: &[u8; N], output: &mut [u8; 8]) -> FfiBenchCall {
    static PREP: OnceLock<c::ir::Program> = OnceLock::new(); let prog = PREP.get_or_init(|| { let mut gp = c::GenParams::profile("wideselect").unwrap(); gp.node_count = N; c::generate(&gp) }); let mut r = vec![0u64; prog.nodes.len()]; let jit = c::stencil::StencilCode::new(prog).expect("jit");
    const ITERS: usize = 16;
    timed! { run {
        let mut acc: u64 = 0;
        let mut k = 0usize;
        while k < ITERS {
            let seed = input[k % N] as u64 ^ (k as u64);
            jit.run(seed, &mut r); acc ^= c::checksum(&r);
            k += 1;
        }
        output.copy_from_slice(&acc.to_le_bytes());
    } }
}
